// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        vm.assume(_target != address(0));
        vm.assume(_target != address(c));
        // Fund contract with some ether
        vm.deal(address(c), 1 ether);
        uint256 balanceBefore = address(c).balance;
        // cap value to avoid underflow
        _value = bound(_value, 0, balanceBefore);
        c.sendMoney(_target, _value, _data);
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter <= balanceBefore - _value + 1 wei); // Allow 1 wei rounding tolerance (excess gas refund)
    }
}

